    'mat2 mul(mat2 x, mat2 y) { return x * y; }\nmat3 mul(mat3 x, mat3 y) { return x * y; }\nmat4 mul(mat4 x, mat4 y) { return x * y; }\nvec2 mul(mat2 x, vec2 y) { return x * y; }\nvec3 mul(mat3 x, vec3 y) { return x * y; }\nvec4 mul(mat4 x, vec4 y) { return x * y; }\nvec2 mul(vec2 x, mat2 y) { return mul(y, x); }\nvec3 mul(vec3 x, mat3 y) { return mul(y, x); }\nvec4 mul(vec4 x, mat4 y) { return mul(y, x); }\n\nfloat saturate(float x){ return clamp(x, 0.0, 1.0); }\nvec2 saturate(vec2 x){ return vec2(saturate(x.x), saturate(x.y)); }\nvec3 saturate(vec3 x){ return vec3(saturate(x.x), saturate(x.y), saturate(x.z)); }\nvec4 saturate(vec4 x){ return vec4(saturate(x.x), saturate(x.y), saturate(x.z), saturate(x.w)); }\n\nfloat rsqrt(float x){ return inversesqrt(x); }\nfloat ldexp(float x, int exp){ return x * exp2(float(exp)); }\n\nfloat lerp(float x, float y, float a){ return mix(x, y, a); }\nvec2 lerp(vec2 x, vec2 y, vec2 a){ return mix(x, y, a); }\nvec3 lerp(vec3 x, vec3 y, vec3 a){ return mix(x, y, a); }\nvec4 lerp(vec4 x, vec4 y, vec4 a){ return mix(x, y, a); }\nvec2 lerp(vec2 x, vec2 y, float a){ return mix(x, y, a); }\nvec3 lerp(vec3 x, vec3 y, float a){ return mix(x, y, a); }\nvec4 lerp(vec4 x, vec4 y, float a){ return mix(x, y, a); }\n\nvec3 GammaToLinearSpace (vec3 sRGB){\n\t\treturn sRGB * (sRGB * (sRGB * 0.305306011 + 0.682171111) + 0.012522878);\n}\nvec3 LinearToGammaSpace (vec3 linRGB){\n\t\tlinRGB = max(linRGB, vec3(0.0));\n\t\treturn max(1.055 * pow(linRGB, vec3(0.416666667)) - 0.055, 0.0);\n}\n\nvec3 SHEvalLinearL0L1 (vec4 normal){\n    vec3 x;\n\n    vec4 t = vec4(0.0,0.0,0.0,1.0);\n    x.r = dot(t,normal); //x.r = dot(unity_SHAr,normal);\n    x.g = dot(t,normal); //x.g = dot(unity_SHAg,normal);\n    x.b = dot(t,normal); //x.b = dot(unity_SHAb,normal);\n\n    return x;\n}\n\nvec3 SHEvalLinearL2 (vec4 normal)\n{\n    vec3 x1, x2;\n    vec4 t = vec4(0.0,0.0,0.0,0.0);\n    vec4 vB = normal.xyzz * normal.yzzx;\n    x1.r = dot(t,vB);//x1.r = dot(unity_SHBr,vB);\n    x1.g = dot(t,vB);//x1.g = dot(unity_SHBg,vB);\n    x1.b = dot(t,vB);//x1.b = dot(unity_SHBb,vB);\n\n    float vC = normal.x*normal.x - normal.y*normal.y;\n    x2 = t.rgb * vC;\n\n    return x1 + x2;\n}\nfloat ShadeSH9(vec4 normal){ \n    vec3 res = SHEvalLinearL0L1(normal);\n    res += SHEvalLinearL2(normal);\n    // res = LinearToGammaSpace(res);\n    return 0.0; \n}\nvec2 TransformUV(vec2 uv, vec4 st){ return (vec2(uv.x, uv.y - 1.0) * st.xy) + st.zw; }\n\nvec3 UnpackNormal(vec3 packednormal){ \n    // return vec3(2.0 * packednormal.x - 1.0, 1.0 - 2.0 * packednormal.y, 2.0 * packednormal.z - 1.0);\n    return packednormal.xyz * 2.0 - 1.0; \n    // return packednormal.xyz;\n    \n    // vec3 normal;\n    // normal.xy = packednormal.wy * 2.0 - 1.0;\n    // normal.z = sqrt(1.0 - saturate(dot(normal.xy, normal.xy)));\n    // return normal;\n\n    // packednormal.x *= packednormal.w;\n    // vec3 normal;\n    // normal.xy = packednormal.xy * 2.0 - 1.0;\n    // normal.z = sqrt(1.0 - saturate(dot(normal.xy, normal.xy)));\n    // return normal;\n}\nvec3 UnpackNormal(vec4 packednormal){ return UnpackNormal(packednormal.xyz); }\n\n// vec4 ObjectToClipPos(mat4 matWorld, vec3 pos) { return mul(u_ViewProjection, mul(matWorld, vec4(pos, 1.0))); }\n// vec4 ObjectToClipPos(mat4 matWorld, vec4 pos) { return ObjectToClipPos(matWorld, pos.xyz); }\n\n// vec3 ObjectToWorldDir(mat3 matWorld, vec3 dir){ return normalize(mul(matWorld, dir)); }\n\n// vec3 ObjectToWorldNormal(vec3 norm){\n//     // #ifdef UNITY_ASSUME_UNIFORM_SCALING\n//     //     return ObjectToWorldDir(norm);\n//     // #else\n//     //     return normalize(mul(norm, (float3x3)unity_WorldToObject));\n//     // #endif\n//     return ObjectToWorldDir(norm);\n// }\n\n// vec2 TransformViewToProjection(vec2 v) { return mul(mat2(u_Projection), v); }\n// vec3 TransformViewToProjection(vec3 v) { return mul(mat3(u_Projection), v); }\n\n// vec3 WorldSpaceViewDir(vec3 worldPos){ return u_CameraPos - worldPos; }\n\n// vec3 WorldSpaceLightDir(vec3 worldPos ){ return u_DirectionLight.Position - worldPos; }', 
